'use strict';
const PUSH_LABELS={urgent:['Nhờ mua thêm ngay','Thành viên bấm gửi: món, số lượng, cửa hàng, ghi chú.'],attendance:['Nhắc báo cơm','Khoảng giờ báo cơm, khi còn người chưa xác nhận.'],prep:['Chuẩn bị bữa tối','Nhắc sơ chế khi bữa tối chưa được ghi nhận đã nấu.'],shopping:['Việc đi chợ chưa xong','Có yêu cầu mua thêm trong hôm nay chưa hoàn thành.'],expiry:['Kiểm tra hạn dùng','Lô có hạn dùng bạn nhập trong hôm nay / ngày mai.'],receipt:['Nhớ nhập receipt','Đã tick mua hôm nay nhưng chưa có hóa đơn cùng ngày.'],budget:['Ngân sách tuần','Thông báo một lần mỗi tuần khi chi thực tế vượt mục tiêu.'],weekly:['Lên thực đơn tuần mới','Chủ Nhật khoảng 18:00, gợi ý chuẩn bị tuần tới.']};
let pushStatusCache={configured:false,publicKey:null,devices:[]},requestDraftId=null;
function pushDeviceId(){let id=localStorage.getItem('bep-push-device-id');if(!id){id=uid();localStorage.setItem('bep-push-device-id',id)}return id}
function pushProfile(){try{return JSON.parse(localStorage.getItem('bep-push-profile')||'null')||{}}catch{return{}}}
async function refreshPushStatus(){if(!cloudConnection.connected)return;try{const res=await familyRequest('push-status');if(res.ok)pushStatusCache=await res.json()}catch{}}
async function pushSettings(){await refreshPushStatus();const profile=pushProfile(),supported='Notification'in window&&'PushManager'in window&&'serviceWorker'in navigator,permission='Notification'in window?Notification.permission:'unsupported',id=pushDeviceId();modal('Push: nhắc việc & người nhận',`<p class="hint"><b>Ai gửi?</b> Server Netlify gửi tự động theo lịch đã bật. Khi cần đồ gấp, một thành viên bấm “Nhờ mua thêm”, server chuyển nội dung đến người được chọn. Thiết bị nhận phải đăng ký trước.</p><div class="status-line"><span>Thiết bị này</span><span class="pill ${permission==='granted'?'':'orange'}">${{granted:'Đã cho phép',denied:'Đang chặn',default:'Chưa cấp quyền',unsupported:'Chưa hỗ trợ'}[permission]}</span></div><div class="status-line"><span>Lưu dữ liệu chung</span><span class="pill ${cloudConnection.connected?'':'orange'}">${cloudConnection.connected?'Đã kết nối Netlify':'Chưa kết nối Netlify'}</span></div>${!cloudConnection.available?'<div class="callout">Bản review không chạy Netlify Functions. Deploy gói trên Netlify, đặt FAMILY_PASSWORD và kết nối gia đình để dùng push thật.</div>':''}<form id="push-device-form"><div class="form-grid"><div class="field"><label for="push-member">Điện thoại này của ai?</label><select id="push-member">${state.members.map(m=>`<option value="${m.id}" ${profile.memberId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="push-label">Tên thiết bị</label><input id="push-label" maxlength="80" value="${esc(profile.label||'Điện thoại của tôi')}" placeholder="Ví dụ: iPhone của Mẹ"></div></div><h3>Những việc muốn nhận push</h3><div class="push-type-list">${Object.entries(PUSH_LABELS).map(([key,[name,note]])=>`<label class="checked-label"><input class="check push-type" type="checkbox" value="${key}" ${profile.types?.[key]!==false?'checked':''}><span>${name}<small style="display:block">${note}</small></span></label>`).join('')}</div><div class="form-grid topspace"><div class="field"><label for="push-quiet-start">Yên lặng từ</label><input id="push-quiet-start" type="time" required value="${profile.quietStart||state.preferences.quietStart||'21:00'}"></div><div class="field"><label for="push-quiet-end">Đến</label><input id="push-quiet-end" type="time" required value="${profile.quietEnd||state.preferences.quietEnd||'07:00'}"></div></div></form><p class="hint">Lịch tự động kiểm tra 15 phút/lần theo Australia/Sydney, có tính giờ mùa hè. Giờ yên lặng áp dụng lịch tự động; yêu cầu “mua thêm ngay” do người gửi chủ động gửi. Thời điểm nhận và âm thanh còn phụ thuộc mạng, quyền thông báo và chế độ tập trung của điện thoại.</p><h3>Thiết bị đã đăng ký</h3>${pushStatusCache.devices.map(d=>`<div class="push-device-row">${esc(d.label)} · ${esc(state.members.find(m=>m.id===d.memberId)?.name||'Thành viên đã bỏ')}${d.deviceId===id?' · Thiết bị này':''}</div>`).join('')||'<p class="hint">Chưa có thiết bị nhận. Mỗi điện thoại cần mở app và bật push.</p>'}<p class="hint topspace">iPhone: thêm app vào Màn hình chính rồi mở từ biểu tượng trước khi bật push. Android: mở website HTTPS, cài PWA nếu trình duyệt yêu cầu.</p>`,`<button class="btn" data-feature="cloud-settings">Kết nối Netlify</button>${pushStatusCache.devices.some(d=>d.deviceId===id)?'<button class="btn" data-push-action="unsubscribe">Tắt thiết bị này</button>':''}<button class="btn primary" data-push-action="subscribe" ${!supported||!cloudConnection.connected?'disabled':''}>${pushStatusCache.devices.some(d=>d.deviceId===id)?'Lưu tùy chọn push':'Bật push thiết bị này'}</button>`,true)}
remindersModal=pushSettings;
function vapidBytes(base64){const padding='='.repeat((4-base64.length%4)%4),raw=atob((base64+padding).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function subscribeDevice(){if(!cloudConnection.connected){toast('Kết nối Netlify trước.',true);return}const profile={deviceId:pushDeviceId(),memberId:$('#push-member').value,label:$('#push-label').value.trim()||'Điện thoại gia đình',types:Object.fromEntries($$('.push-type').map(el=>[el.value,el.checked])),quietStart:$('#push-quiet-start').value,quietEnd:$('#push-quiet-end').value};let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted'){toast('Chưa được cấp quyền thông báo. Kiểm tra cài đặt của trình duyệt / iPhone.',true);return}try{const registration=await navigator.serviceWorker.getRegistration();if(!registration?.active){toast('Service Worker chưa sẵn sàng. Tải lại app rồi thử.',true);return}const keyResponse=await familyRequest('push-key',{method:'POST'});if(!keyResponse.ok)throw Error('Chưa tạo được khóa push trên Netlify.');const{publicKey}=await keyResponse.json();let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidBytes(publicKey)});const response=await familyRequest('push-subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...profile,subscription:subscription.toJSON()})});if(!response.ok){const result=await response.json();throw Error(result.error||'Netlify chưa lưu được thiết bị nhận.')}localStorage.setItem('bep-push-profile',JSON.stringify(profile));toast('Đã đăng ký thiết bị nhận push.');await pushSettings()}catch(error){toast(error.message||'Chưa bật được push. Mở app từ Màn hình chính trên iPhone.',true)}}
async function unsubscribeDevice(){try{const registration=await navigator.serviceWorker.getRegistration(),subscription=await registration?.pushManager.getSubscription();if(subscription)await subscription.unsubscribe();if(cloudConnection.connected)await familyRequest('push-unsubscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({deviceId:pushDeviceId()})});localStorage.removeItem('bep-push-profile');toast('Đã tắt nhận push trên thiết bị này.');await pushSettings()}catch(error){toast('Chưa hoàn tất tắt push. Kiểm tra cài đặt thông báo của điện thoại.',true)}}
async function requestItemForm(){await refreshPushStatus();requestDraftId=uid();const profile=pushProfile(),sender=profile.memberId||state.members[0].id,deviceMembers=new Set(pushStatusCache.devices.map(d=>d.memberId));modal('Quên ghi đồ? Nhờ mua thêm ngay',`<p class="hint">Nhập một yêu cầu rõ ràng. App thêm vào danh sách mua và giữ nội dung cho người mua; bạn chọn gửi push hoặc chia sẻ nếu chưa có thiết bị nhận.</p><form id="errand-form"><div class="field"><label for="errand-item">Cần mua gì?</label><input id="errand-item" name="item" maxlength="150" required placeholder="Ví dụ: rau mùi, đùi gà, sữa cho bé…"></div><div class="form-grid"><div class="field"><label for="errand-qty">Số lượng / cách mua</label><input id="errand-qty" name="qty" maxlength="80" required placeholder="2 cái / 1 bó / 500 g"></div><div class="field"><label for="errand-cost">Dự kiến tổng tiền AUD (tùy chọn)</label><input id="errand-cost" name="cost" type="number" min="0" max="10000" step=".01" placeholder="Chưa biết — để trống"></div></div><div class="field"><label for="errand-store">Mua tại đâu?</label><select id="errand-store" name="storeId"><option value="">Tùy nơi / chưa chọn</option>${(state.stores||[]).map(s=>`<option value="${s.id}">${esc(s.name)}${s.address?' · '+esc(s.address):''}</option>`).join('')}</select></div><div class="field"><label for="errand-note">Ghi chú để người mua hiểu ngay</label><textarea id="errand-note" name="note" maxlength="500" placeholder="Ví dụ: bó nhỏ, không có thì mua hành lá thay; cần cho bữa tối nay."></textarea></div><div class="field"><label for="errand-from">Người nhờ mua</label><select id="errand-from" name="fromId">${state.members.map(m=>`<option value="${m.id}" ${sender===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><h3>Gửi đến ai?</h3>${state.members.map(m=>`<label class="checked-label"><input class="check errand-target" type="checkbox" name="targets" value="${m.id}" ${deviceMembers.has(m.id)||!deviceMembers.size&&m.id!==sender?'checked':''}><span>${esc(m.name)} <small>${deviceMembers.has(m.id)?'có thiết bị đăng ký':'chưa có thiết bị push'}</small></span></label>`).join('')}<label class="checked-label topspace"><input class="check" id="errand-push" type="checkbox" checked> Gửi push ngay sau khi thêm</label><p class="hint">Tài khoản gia đình dùng chung mật khẩu; tên người gửi do bạn chọn, không phải xác thực tài khoản cá nhân. Push chỉ gửi đến các thiết bị đã bật mục “Nhờ mua thêm ngay”.</p></form>`,`<button class="btn" data-push-action="settings">Cài người nhận</button><button class="btn primary" data-action="submit-form" data-id="errand-form">Thêm & gửi yêu cầu</button>`,true)}
function requestText(r){const store=getShop(state,r.storeId);return[`🛒 Nhờ mua thêm: ${r.qty} ${r.item}`,store?`📍 ${store.name}${store.address?' — '+store.address:''}`:'📍 Tùy cửa hàng thuận tiện',r.note?'📝 '+r.note:'',`Từ ${r.from||'Nhà mình'} · ${dateLabel(r.date)}`].filter(Boolean).join('\n')}
async function sendErrand(r,{first=false}={}){if(!cloudConnection.connected){modal('Đã thêm đồ, chưa gửi được push',`<p class="hint">Kết nối Netlify và đăng ký điện thoại người nhận trước. Yêu cầu vẫn nằm trong danh sách mua.</p><textarea id="errand-share-text" class="input" rows="6" readonly>${esc(requestText(r))}</textarea>`,`<button class="btn" data-push-action="share-request" data-id="${r.id}">Chia sẻ / Messenger</button><button class="btn primary" data-push-action="settings">Cài push</button>`);return}try{const response=await familyRequest('push-send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'urgent',requestId:uid(),title:`${r.from||'Nhà mình'} nhờ mua thêm`,body:requestText(r),targets:r.targets})});const result=await response.json();if(!response.ok)throw Error(result.error||'Netlify chưa gửi được push.');if(result.accepted){r.pushAccepted=result.accepted;r.pushAt=new Date().toISOString();save(`Đã gửi đến dịch vụ push cho ${result.accepted} thiết bị; chưa xác nhận đã đọc.`);render()}else{modal('Yêu cầu đã lưu; push chưa được nhận gửi',`<p>${result.reason==='no_recipient'?'Chưa có thiết bị phù hợp đã bật nhận yêu cầu mua thêm.':result.reason==='not_configured'?'Chưa có đăng ký push trên Netlify.':'Dịch vụ push chưa nhận được yêu cầu. Thử lại hoặc chia sẻ nội dung.'}</p><textarea class="input" rows="6" readonly>${esc(requestText(r))}</textarea>`,`<button class="btn" data-push-action="share-request" data-id="${r.id}">Chia sẻ nội dung</button><button class="btn primary" data-push-action="settings">Cài người nhận</button>`)}}catch(error){toast('Đã giữ yêu cầu trong danh sách; chưa gửi được push. '+error.message,true)}}
document.addEventListener('submit',async event=>{if(event.target.id!=='errand-form')return;event.preventDefault();const form=event.target,d=new FormData(form),v=Object.fromEntries(d),targets=d.getAll('targets');if(!targets.length){toast('Chọn ít nhất một người nhận.',true);return}const sender=state.members.find(m=>m.id===v.fromId),r={id:requestDraftId||uid(),item:v.item.trim(),qty:v.qty.trim(),storeId:v.storeId,note:v.note.trim(),from:sender?.name||'Nhà mình',targets,date:sydneyDate(),createdAt:new Date().toISOString(),done:false,pushAccepted:0};if(!r.item||!r.qty)return;const shouldPush=$('#errand-push').checked;state.errands??=[];state.errands.push(r);const week=ensureWeek(state,monday(r.date));week.extras.push({id:uid(),name:r.item,qty:r.qty,cost:v.cost===''?0:+v.cost,costUnknown:v.cost==='',storeId:r.storeId,errandId:r.id,done:false});log(`Nhờ mua thêm ${r.qty} ${r.item}`);save('Đã thêm yêu cầu vào danh sách mua.');closeModal();view='shopping';location.hash='shopping';weekStart=monday(r.date);selectedDate=r.date;render();if(shouldPush)await sendErrand(r,{first:true})});
document.addEventListener('click',async event=>{const el=event.target.closest('[data-push-action]');if(!el)return;try{switch(el.dataset.pushAction){case'settings':await pushSettings();break;case'subscribe':await subscribeDevice();break;case'unsubscribe':await unsubscribeDevice();break;case'request-item':await requestItemForm();break;case'resend-request':{const r=(state.errands||[]).find(r=>r.id===el.dataset.id);if(r)await sendErrand(r);break}case'share-request':{const r=(state.errands||[]).find(r=>r.id===el.dataset.id);if(r)await shareText(requestText(r));break}}}catch(error){toast(error.message||'Chưa thực hiện được thao tác push.',true)}});
render();
